// Build the catalog from the Data Table (staff-editable, no code changes).
// Falls back to the baked-in DEMO catalog when the table is unreachable.
const inp = $input.first().json;
let rows = [];
if (inp.error === undefined) {
  const d = Array.isArray(inp.data) ? inp.data : (Array.isArray(inp) ? inp : []);
  rows = d.filter((r) => r && r.kind && r.name);
}
const services = rows.filter((r) => r.kind === 'service').map((r) => ({
  name: r.name, price: Number(r.price) || 0, minutes: Number(r.minutes) || 30,
  buffer: Number(r.buffer) || 15, prep: r.prep || '' }));
const doctors = rows.filter((r) => r.kind === 'doctor').map((r) => {
  const parts = String(r.info || '').split('|').map((x) => x.trim());
  return { name: r.name, specialty: parts[0] || '', days: parts[1] || '', hours: parts[2] || '' }; });
const clin = rows.find((r) => r.kind === 'clinic');
const kv = {};
String((clin && clin.info) || '').split('|').forEach((p) => {
  const i = p.indexOf('='); if (i > 0) { kv[p.slice(0, i).trim()] = p.slice(i + 1).trim(); } });
if (!services.length) {
  return [{ json: { clinic: 'عيادة النور لطب الأسنان (DEMO)', currency: 'EGP',
    services: [{ name: 'General exam', price: 300, minutes: 30, buffer: 15, prep: '' }],
    doctors: [{ name: 'Dr. Samir', specialty: 'general dentistry', days: '', hours: '' }],
    hours: '', phone: '', address: '', cancelPolicy: '', _fallback: true } }];
}
return [{ json: { clinic: (clin && clin.name) || '', currency: 'EGP', services: services,
  doctors: doctors, hours: kv.hours || '', phone: kv.phone || '', address: kv.address || '',
  cancelPolicy: kv.cancel || '' } }];
